// WP-8 / HIGH-03: app ACL manifest. Declaring the command list makes Tauri enforce the ACL for
// app commands: a command is only callable from a window whose capability grants its
// `allow-<command>` permission (autogenerated into `permissions/autogenerated/`). Permission
// sets live in `permissions/*.toml`, the window grant in `capabilities/default.json`.
//
// Before running tauri-build this script verifies (and fails the build otherwise) that
// `APP_COMMANDS` == the `tauri::generate_handler![...]` list in `src/lib.rs` == the
// `#[tauri::command]` functions in `src/commands.rs`, and that every command is granted by
// exactly one permission set in `permissions/*.toml`.
include!("src/app_commands.rs");

use std::collections::BTreeMap;
use std::collections::BTreeSet;
use std::fs;

fn read(path: &str) -> String {
    println!("cargo:rerun-if-changed={path}");
    fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"))
}

fn ident_after(s: &str) -> String {
    s.chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
        .collect()
}

/// `commands::<name>` entries inside `generate_handler![ ... ]`.
fn handler_commands(lib_rs: &str) -> Vec<String> {
    let start = lib_rs
        .find("generate_handler![")
        .expect("src/lib.rs: generate_handler![ not found");
    let rest = &lib_rs[start..];
    let end = rest
        .find(']')
        .expect("src/lib.rs: unterminated generate_handler!");
    rest[..end]
        .split("commands::")
        .skip(1)
        .map(ident_after)
        .collect()
}

/// Function names directly following a `#[tauri::command]` attribute (other attributes and
/// doc comments in between are skipped).
fn annotated_commands(commands_rs: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut pending = false;
    for line in commands_rs.lines() {
        let t = line.trim();
        if t == "#[tauri::command]" {
            pending = true;
            continue;
        }
        if !pending {
            continue;
        }
        if t.starts_with("#[") || t.starts_with("//") || t.is_empty() {
            continue;
        }
        let sig = t
            .trim_start_matches("pub ")
            .trim_start_matches("async ")
            .trim_start_matches("fn ");
        out.push(ident_after(sig));
        pending = false;
    }
    out
}

/// `"allow-<slug>"` entries per hand-written permission file.
fn permission_set_grants() -> BTreeMap<String, Vec<String>> {
    println!("cargo:rerun-if-changed=permissions");
    let mut grants = BTreeMap::new();
    for entry in fs::read_dir("permissions").expect("read permissions/") {
        let path = entry.expect("permissions entry").path();
        if path.extension().and_then(|e| e.to_str()) != Some("toml") {
            continue; // skips `autogenerated/` (directory) and non-toml files
        }
        let path_s = path.to_string_lossy().into_owned();
        let body = read(&path_s);
        let allows = body
            .split("\"allow-")
            .skip(1)
            .map(|s| s.split('"').next().unwrap_or_default().to_string())
            .collect();
        grants.insert(path_s, allows);
    }
    grants
}

fn verify_command_lists() {
    let manifest: Vec<String> = APP_COMMANDS.iter().map(|s| s.to_string()).collect();
    let manifest_set: BTreeSet<&String> = manifest.iter().collect();
    assert_eq!(
        manifest_set.len(),
        manifest.len(),
        "src/app_commands.rs: duplicate command names"
    );

    let handler = handler_commands(&read("src/lib.rs"));
    assert_eq!(
        handler, manifest,
        "src/lib.rs generate_handler! and src/app_commands.rs APP_COMMANDS differ (same order required)"
    );

    let annotated: BTreeSet<String> = annotated_commands(&read("src/commands.rs"))
        .into_iter()
        .collect();
    let manifest_owned: BTreeSet<String> = manifest.iter().cloned().collect();
    assert_eq!(
        annotated, manifest_owned,
        "#[tauri::command] functions in src/commands.rs and APP_COMMANDS differ"
    );

    let mut granted: BTreeMap<String, String> = BTreeMap::new();
    for (file, allows) in permission_set_grants() {
        for slug in allows {
            let cmd = slug.replace('-', "_");
            assert!(
                manifest_owned.contains(&cmd),
                "{file}: allow-{slug} does not name an app command"
            );
            if let Some(prev) = granted.insert(cmd.clone(), file.clone()) {
                panic!("{cmd} is granted by both {prev} and {file}; use exactly one set");
            }
        }
    }
    let missing: Vec<&String> = manifest_owned
        .iter()
        .filter(|c| !granted.contains_key(*c))
        .collect();
    assert!(
        missing.is_empty(),
        "commands not granted by any permissions/*.toml set: {missing:?}"
    );
}

fn main() {
    // update-check-v1: CI embeds the GitHub run number (read via `option_env!`).
    println!("cargo:rerun-if-env-changed=NEXUS_BUILD_NUMBER");
    println!("cargo:rerun-if-changed=src/app_commands.rs");
    verify_command_lists();
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
